const $=s=>document.querySelector(s), cats=['Tops','Bottoms','Shoes','Accessories'];
function drawing(cat,color){const shapes={Tops:`<path d="M68 44 98 30Q120 50 142 30L172 44 199 91 169 108 156 88 158 216H82L84 88 71 108 41 91Z"/><path d="m98 30 22 38 22-38M120 68v35" fill="none" stroke="#716e603f" stroke-width="3"/>`,Bottoms:`<path d="M77 27h88l9 198h-43l-11-133-11 133H66Z"/><path d="M77 47h88M120 28v64M80 54q13 25 30 0M158 54q-13 25-28 0" fill="none" stroke="#0003" stroke-width="3"/>`,Shoes:`<path d="m43 106 27-31 32 16 14 31 62 19q22 5 22 25H35q-12-17 8-60Z"/><path d="M35 166h165v15H33Zm65-58 24-6m-18 18 25-6m-13 18 25-6" fill="#e9e4d6" stroke="#8886" stroke-width="3"/>`,Accessories:`<path d="M98 24h44v62H98Zm0 143h44v62H98Z"/><circle cx="120" cy="126" r="49" fill="#b59a63"/><circle cx="120" cy="126" r="40" fill="#f4f0df"/><path d="M120 96v30l20 12" fill="none" stroke="#424b39" stroke-width="4"/>`};return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="240" height="250" viewBox="0 0 240 250"><g fill="${color}" stroke="#373b3020" stroke-width="1.5" stroke-linejoin="round">${shapes[cat]}</g></svg>`)}
const demo=[['Everyday cream polo','Tops','#d9cfb9'],['Relaxed olive trousers','Bottoms','#6c7559'],['Classic white sneakers','Shoes','#dedcd2'],['The everyday watch','Accessories','#7d593d'],['Midnight cotton tee','Tops','#3e4847'],['Straight-leg denim','Bottoms','#647c8b'],['Warm suede sneakers','Shoes','#b59a76'],['Soft sage polo','Tops','#9ca58c']].map(([name,category,c],i)=>({id:'demo'+i,name,category,photo:drawing(category,c),demo:true}));
let state={items:demo,saved:[],look:[]},db,filter='All pieces',view='wardrobe',locks=new Set(),photo='',timer;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function persist(next){return new Promise((resolve,reject)=>{if(!db)return reject(Error('Storage unavailable'));const tx=db.transaction('data','readwrite');tx.objectStore('data').put(next,'wardrobe');tx.oncomplete=()=>{state=next;resolve()};tx.onerror=()=>reject(tx.error)})}
async function update(next){try{await persist(next);render();return true}catch(e){toast('Could not save. Check browser storage space and try again.');return false}}
function pick(items,previous){const options=items.filter(i=>i.id!==previous);return (options.length?options:items)[Math.floor(Math.random()*(options.length||items.length))]}
async function shuffle(){const missing=cats.slice(0,3).filter(c=>!state.items.some(i=>i.category===c));if(missing.length){toast('Add '+missing.join(', ').toLowerCase()+' to create a complete outfit.');return}const look=cats.map(c=>{const options=state.items.filter(i=>i.category===c);const prev=state.look.find(i=>i.category===c);return locks.has(c)&&prev&&options.some(i=>i.id===prev.id)?prev:options.length?pick(options,prev?.id):null}).filter(Boolean);if(await update({...state,look}))toast('A fresh combination, just for you.');}
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function picture(item){const img=el('img');img.src=item.photo;img.alt=item.name;return img}
function render(){const out=$('#outfit');out.replaceChildren();state.look.forEach(item=>{const wrap=el('div','look-piece');wrap.append(picture(item));const b=el('button','',locks.has(item.category)?'● Locked':'○ Lock');b.title='Keep '+item.name+' when shuffling';b.setAttribute('aria-pressed',locks.has(item.category));b.onclick=()=>{locks.has(item.category)?locks.delete(item.category):locks.add(item.category);render()};wrap.append(b);out.append(wrap)});if(!state.look.length)out.append(el('p','empty','Add your pieces, then style your day.'));$('#outfit-desc').textContent=state.look.some(i=>i.demo)?'Featuring demo pieces · add your photos below.':'From your closet, with a fresh perspective.';$('#saved-count').textContent=state.saved.length;$('#item-count').textContent=state.items.length+' pieces';$('#section-title').firstChild.textContent=view==='wardrobe'?'Your wardrobe ':'Saved outfits ';$('#item-count').hidden=view!=='wardrobe';$('#section-label').textContent=view==='wardrobe'?'GOOD STYLE STARTS HERE':'LOOKS YOU LOVE';$('#demo-note').hidden=view!=='wardrobe'||!state.items.some(i=>i.demo);$('.toolbar').hidden=view!=='wardrobe';$('#filters').replaceChildren();['All pieces',...cats].forEach(c=>{const b=el('button',filter===c?'active':'',c);b.onclick=()=>{filter=c;render()};$('#filters').append(b)});const grid=$('#grid');grid.replaceChildren();if(view==='saved'){state.saved.forEach(s=>{const card=el('article','saved-card'),mini=el('div','mini');s.items.forEach(i=>mini.append(picture(i)));card.append(mini,el('h3','',s.name));const actions=el('div','saved-actions'),wear=el('button','','Wear this look ↗'),del=el('button','','Remove');wear.onclick=async()=>{locks.clear();await update({...state,look:s.items});window.scrollTo({top:0,behavior:'smooth'})};del.onclick=()=>update({...state,saved:state.saved.filter(x=>x.id!==s.id)});actions.append(wear,del);card.append(actions);grid.append(card)});}else{state.items.filter(i=>(filter==='All pieces'||i.category===filter)&&i.name.toLowerCase().includes($('#search').value.toLowerCase())).forEach(item=>{const card=el('article','card'),box=el('div','piece-image');box.append(picture(item),el('span','tag',item.demo?'DEMO':item.category.toUpperCase()));const del=el('button','delete','×');del.setAttribute('aria-label','Remove '+item.name);del.onclick=async()=>{if(!confirm('Remove '+item.name+' from your wardrobe?'))return;locks.delete(item.category);await update({...state,items:state.items.filter(i=>i.id!==item.id),look:state.look.filter(i=>i.id!==item.id)})};box.append(del);card.append(box,el('h3','',item.name),el('p','',item.category));grid.append(card)})}if(!grid.children.length)grid.append(el('div','empty',view==='saved'?'Your favorite looks will live here. Tap ♡ to save an outfit.':'No pieces here yet. Add a photo to get started.'))}
$('#date').textContent=new Date().toLocaleDateString('en',{month:'short',day:'numeric'}).toUpperCase();$('.intro #shuffle').onclick=shuffle;$('#search').oninput=render;document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n===b));render()});$('#add').onclick=()=>{$('#form').reset();photo='';$('#preview').hidden=true;$('#upload-text').hidden=false;$('#form-error').textContent='';$('#modal').showModal()};$('#close').onclick=()=>$('#modal').close();$('#camera-button').onclick=()=>$('#camera').click();
async function readPhoto(file){if(!file)return;if(!file.type.startsWith('image/')||file.size>15*1024*1024){$('#form-error').textContent='Choose an image smaller than 15 MB.';return}try{const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas'),scale=Math.min(1,1000/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();photo=canvas.toDataURL('image/jpeg',.85);$('#preview').src=photo;$('#preview').hidden=false;$('#upload-text').hidden=true;$('#form-error').textContent=''}catch{$('#form-error').textContent='This image could not be read. Try a JPG, PNG or WebP.'}}
$('#photo').onchange=e=>readPhoto(e.target.files[0]);$('#camera').onchange=e=>readPhoto(e.target.files[0]);$('#form').onsubmit=async e=>{e.preventDefault();const name=$('#name').value.trim();if(!photo||!name){$('#form-error').textContent='Add a photo and a name first.';return}const item={id:crypto.randomUUID(),name,category:$('#category').value,photo};if(await update({...state,items:[...state.items,item]})){$('#modal').close();toast('Your new piece is in the wardrobe.')}};$('#save').onclick=async()=>{if(state.look.length<3){toast('Generate a complete outfit first.');return}if(state.saved.some(s=>s.items.map(i=>i.id).join()===state.look.map(i=>i.id).join())){toast('This look is already saved.');return}if(await update({...state,saved:[{id:crypto.randomUUID(),name:'Daily edit · '+new Date().toLocaleDateString('en',{month:'short',day:'numeric'}),items:state.look},...state.saved]}))toast('Saved to your favorite outfits.');};
const request=indexedDB.open('daywear',1);request.onupgradeneeded=()=>request.result.createObjectStore('data');request.onsuccess=()=>{db=request.result;const get=db.transaction('data').objectStore('data').get('wardrobe');get.onsuccess=async()=>{if(get.result)state=get.result;if(!state.look.length&&state.items.length===demo.length&&state.items.every(i=>i.demo)){state.look=cats.map(c=>state.items.find(i=>i.category===c));await update(state)}render()};get.onerror=()=>{render();toast('Could not load your wardrobe.')}};request.onerror=()=>{render();toast('Browser storage is unavailable. Enable storage to save your wardrobe.')};
